   n
 }

+///|
+fn parse_task(value : Json) -> Task raise StnError {
+  guard value is Object(obj) else {
+    raise StnError("invalid_input", "task must be object")
+  }
+  let id = obj.get("id")
+  let min_duration = obj.get("min_duration")
+  let max_duration = obj.get("max_duration")
+  let release = obj.get("release")
+  let deadline = obj.get("deadline")
+  let resource = obj.get("resource")
+  let expected = if resource is None { 5 } else { 6 }
+  if obj.length() != expected ||
+    id is None ||
+    min_duration is None ||
+    max_duration is None ||
+    release is None ||
+    deadline is None {
+    fields(obj, [
+      "id", "min_duration", "max_duration", "release", "deadline", "resource",
+    ])
+  }
+  let resource = match resource {
+    None | Some(Null) => None
+    Some(v) => Some(text(v, "resource"))
+  }
+  {
+    id: text(required_value(id, "id"), "id"),
+    min_duration: plan_int(required_value(min_duration, "min_duration")),
+    max_duration: plan_int(required_value(max_duration, "max_duration")),
+    release: plan_int(required_value(release, "release")),
+    deadline: plan_int(required_value(deadline, "deadline")),
+    resource,
+  }
+}
+
+///|
+fn parse_dependency(value : Json) -> Dependency raise StnError {
+  guard value is Object(obj) else {
+    raise StnError("invalid_input", "dependency must be object")
+  }
+  let before = obj.get("before")
+  let after = obj.get("after")
+  let kind = obj.get("kind")
+  let min_lag = obj.get("min_lag")
+  let max_lag = obj.get("max_lag")
+  let expected = if max_lag is None { 4 } else { 5 }
+  if obj.length() != expected ||
+    before is None ||
+    after is None ||
+    kind is None ||
+    min_lag is None {
+    fields(obj, ["before", "after", "kind", "min_lag", "max_lag"])
+  }
+  let max_lag = match max_lag {
+    None | Some(Null) => None
+    Some(v) => Some(plan_int(v))
+  }
+  {
+    before: text(required_value(before, "before"), "before"),
+    after: text(required_value(after, "after"), "after"),
+    kind: text(required_value(kind, "kind"), "kind"),
+    min_lag: plan_int(required_value(min_lag, "min_lag")),
+    max_lag,
+  }
+}
+
 ///|
 pub fn analyze_plan(value : Json) -> Json raise StnError {
   guard value is Object(obj) else {
@@ -18,49 +85,14 @@ pub fn analyze_plan(value : Json) -> Json raise StnError {
   if ts.length() > 24 {
     raise StnError("limit_exceeded", "at most 24 tasks")
